<script lang="ts">
 import Icon from '$lib/components/Icon.svelte';import PasswordField from './PasswordField.svelte';import Credentials from './Credentials.svelte';
 import {databaseState,command,newId,validatePassword} from '$lib/database/store';import {engines,presets,type Engine,type Preset,type InitialUser} from '$lib/database/model';import {workspace} from '$lib/stores/workspace';
 export let linkedProject='';export let onCreated:(id:string)=>void=()=>{};
 let engine:Engine='MySQL',name='',username='',password='',mode:'new'|'existing'|'none'='new',privileges:Preset='Full access',existing='',project=linkedProject,error='',credentials:{username:string;password:string}|null=null;
 $: availableUsers=$databaseState.users.filter(u=>u.engine===engine);
 $: projects=$workspace.projects.filter(p=>!$databaseState.databases.some(d=>d.project===p.id));
 function submit(){try{error='';const key=name.trim(),userName=username.trim()||key;let first:InitialUser;if(mode==='new'){validatePassword(password);first={mode:'new',name:userName,preset:privileges};}else if(mode==='existing'){first={mode:'existing',id:existing,preset:privileges};}else first={mode:'none'};const id=newId();command({type:'create',id,userId:newId(),name:key,engine,project:project||null,first});credentials=mode==='new'?{username:userName,password}:null;name='';username='';password='';existing='';project=linkedProject;onCreated(id);}catch(e){error=e instanceof Error?e.message:'Database creation failed.';}}
</script>
<section class="card stack"><div class="section-title"><h3>Create Database</h3><p class="subtitle">Create a database and its first user. Choose a password or generate one automatically.</p></div><form class="stack" on:submit|preventDefault={submit}><div class="db13-form-grid"><label class="field">Database engine<select bind:value={engine} on:change={()=>existing=''}>{#each engines as e}<option value={e}>{e}</option>{/each}</select><small>Choose a database engine.</small></label><label class="field">Database Name<input bind:value={name} required placeholder="e.g. customer_portal"/><small>Lowercase letters, numbers and underscores.</small></label></div>{#if mode==='new'}<PasswordField bind:value={password}/><p class="db13-identity-hint"><Icon name="Key"/><span>Username: <strong>{username||name||'Same as database name'}</strong> · Private access by default</span></p>{/if}<details class="advanced"><summary>Advanced mode</summary><div class="stack"><div class="db13-form-grid"><label class="field">First user<select bind:value={mode} on:change={()=>{password='';existing=''}}><option value="new">Create new user</option><option value="existing">Use existing user</option><option value="none">No user yet</option></select></label>{#if mode!=='none'}<label class="field">Initial privileges<select bind:value={privileges}>{#each presets as p}<option value={p}>{p}</option>{/each}</select></label>{/if}</div>{#if mode==='new'}<label class="field">Custom username<input bind:value={username} placeholder="Same as database name"/></label>{:else if mode==='existing'}<label class="field">Existing user<select bind:value={existing} required><option value="">Select user</option>{#each availableUsers as u}<option value={u.id}>{u.name}</option>{/each}</select></label>{/if}<label class="field">Linked project<select bind:value={project} disabled={!!linkedProject}><option value="">Standalone database</option>{#each projects as p}<option value={p.id}>{p.name}</option>{/each}</select></label></div></details>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="row between wrap db13-action-row"><small>Runs on this server · simulated creation</small><button class="btn primary" type="submit"><Icon name="Plus"/> Create database</button></div></form></section>{#if credentials}<Credentials username={credentials.username} password={credentials.password} onClose={()=>credentials=null}/>{/if}
